-- Written by hand. Carnegie Mellon's MS in Business Analytics publishes only a price per unit and a "usual"
-- number of units, so no total can be taken from the site: the program leaves the database (decision 2026-11-11).
-- Checked before the push: no applications, scholarships, feedback rounds or rankings point to it.
delete from public.programs p
using public.universities u
where p.university_id = u.id
  and u.name = 'Carnegie Mellon University'
  and p.program = 'MS in Business Analytics (full-time)';

-- It was the university's only program: an empty university would show in Add a university (9).
delete from public.universities u
where u.name = 'Carnegie Mellon University'
  and not exists (select 1 from public.programs p where p.university_id = u.id);

-- Costs are shown only as a total or per year (decision 2026-11-11).
alter table public.programs drop constraint programs_cost_unit_check;
alter table public.programs add constraint programs_cost_unit_check
  check (cost_unit in ('per_year', 'total'));
